script.setup:
// Pts does the geometry and the drawing: a grid of points (Create.gridPts), each joined to its
// perpendicular foot on a line swinging through the pointer (Line.perpendicularFromPt), and the
// convex hull of the points near the pointer (Polygon.convexHull). CanvasForm draws on an offscreen
// 2D canvas; the scene uploads it and adds a soft glow from the texture's mipmaps.
const Pts = await ctx.utils.import("https://esm.sh/pts@1.0.1");
const { Pt, Group, Bound, Create, Line, Polygon, CanvasForm, Num } = Pts;
const [w, h] = ctx.resolution, CH = 900, CW = Math.round((CH * w) / h);
const canvas = new OffscreenCanvas(CW, CH), c2 = canvas.getContext("2d");
const form = new CanvasForm(c2);
const gl = ctx.gl, tex = gl.createTexture();
const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_pts; uniform float u_glow;
void main() {
  vec2 uv = vec2(v_uv.x, 1.0 - v_uv.y);
  vec3 c = texture(u_pts, uv).rgb;
  vec3 g = textureLod(u_pts, uv, 3.0).rgb * 0.6 + textureLod(u_pts, uv, 5.0).rgb * 0.8;
  outColor = vec4(c + max(g - 0.03, 0.0) * u_glow, 1.0);
}`;
Object.assign(ctx.state, { Pt, Group, Bound, Create, Line, Polygon, Num, CanvasForm, form, c2, canvas, CW, CH, tex, cols: 0, grid: null, moved: false,
  prog: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
// The drawing canvas follows the screen's shape (landscape, portrait), so nothing is stretched.
if (ctx.resized) {
  const [w, h] = ctx.resolution;
  s.CW = Math.round((s.CH * w) / h);
  s.canvas = new OffscreenCanvas(s.CW, s.CH);
  s.c2 = s.canvas.getContext("2d");
  s.form = new s.CanvasForm(s.c2);
  s.cols = 0;
}
const { Pt, Group, Bound, Create, Line, Polygon, Num, form, c2, CW, CH } = s;
const cols = Math.max(6, u.u_cols | 0);
if (cols !== s.cols) {
  s.cols = cols;
  s.grid = Create.gridPts(Bound.fromGroup([new Pt(0, 0), new Pt(CW, CH)]), cols, Math.round((cols * CH) / CW));
  // a hair of jitter: convexHull (Melkman) trips over exactly collinear grid points
  for (const p of s.grid) p.add(Math.random() - 0.5, Math.random() - 0.5);
}
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
const t = ctx.time;
const pointer = s.moved ? new Pt(ctx.mouse[0] * CW, ctx.mouse[1] * CH) : new Pt(CW * (0.5 + 0.3 * Math.cos(t * 0.4)), CH * (0.5 + 0.25 * Math.sin(t * 0.7)));
// a line through the pointer, swinging slowly
const ang = t * 0.3 * u.u_spin;
const dir = new Pt(Math.cos(ang), Math.sin(ang)).multiply(CW);
const line = new Group(pointer.$subtract(dir), pointer.$add(dir));
c2.fillStyle = "#05060b"; c2.fillRect(0, 0, CW, CH);
const reach = u.u_reach * CH;
const near = [];
for (const p of s.grid) {
  const foot = Line.perpendicularFromPt(line, p);
  if (!foot) continue;
  const d = p.$subtract(pointer).magnitude();
  const k = Num.clamp(1 - d / reach, 0, 1);
  // short ticks far away, long strokes toward the line close to the pointer
  const end = p.$add(foot.$subtract(p).multiply(0.1 + 0.9 * Math.sqrt(k)));
  // warm on one side of the line, cool on the other
  const side = (p[0] - pointer[0]) * dir[1] - (p[1] - pointer[1]) * dir[0] > 0;
  const [r0, g0, b0] = side ? [255, 110, 80] : [80, 200, 255];
  form.stroke(`rgba(${r0},${g0},${b0},${0.18 + 0.75 * k})`, 1.5 + 1.5 * k).line([p, end]);
  form.fillOnly(k > 0 ? "#ffd166" : "#3a4a7a").point(p, 1.5 + 3 * k, "circle");
  if (k > 0) near.push(p);
}
if (near.length > 2) {
  const hull = Polygon.convexHull(near);
  form.fill("rgba(255,120,90,0.05)").stroke("rgba(255,140,110,0.8)", 2).polygon(hull);
}
form.stroke("rgba(255,255,255,0.35)", 1).line(line);
form.fillOnly("#fff").point(pointer, 6, "circle");
ctx.publish("points near", near.length);
gl.bindTexture(gl.TEXTURE_2D, s.tex);
gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.canvas);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
gl.generateMipmap(gl.TEXTURE_2D);
gl.useProgram(s.prog);
ctx.utils.bindTexture(s.prog, "u_pts", s.tex, 0);
ctx.utils.drawFullscreen(s.prog);
